import { plainTime } from '@absoluteui/core';
import { TimePicker } from '@absoluteui/components/time-picker';

const host = document.createElement('div');
document.body.append(host);
const start = TimePicker.create(host, {
  label: 'Opening time',
  name: 'opensAt',
  required: true,
  min: plainTime(6, 0),
  max: plainTime(22, 0),
  step: 15,
});
host.addEventListener('aui-change', () => {
  host.dataset.valid = String(start.validity.valid);
});

import { parsePlainTime } from '@absoluteui/core';
import { TimePicker, type TimePickerChangeDetail } from '@absoluteui/components/time-picker';

const host = document.createElement('div');
document.body.append(host);
TimePicker.create(host, {
  label: 'Backup time',
  granularity: 'second',
  hourCycle: 'h23',
  value: parsePlainTime('02:30:00'),
  validate: (value) => (value !== null && value.hour >= 8 && value.hour < 18 ? 'Choose a time outside office hours.' : null),
});
host.addEventListener('aui-change', (event) => {
  const detail = (event as CustomEvent<TimePickerChangeDetail>).detail;
  host.dataset.time = detail.value ? `${detail.value.hour}:${detail.value.minute}` : '';
});
